// Card codes look like VCH-MOC-000123-7: the last digit is a Luhn check digit
// of the six-digit serial (generated by the database), so most typing errors
// are caught before the code is looked up.
const CARD_CODE = /^VCH-[A-Z]{3}-(\d{6})-(\d)$/;

export function luhnCheckDigit(digits: string): number {
  let sum = 0;
  let double = true;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = Number(digits[i]);
    if (double) { d *= 2; if (d > 9) d -= 9; }
    sum += d;
    double = !double;
  }
  return (10 - (sum % 10)) % 10;
}

// False only for a card code whose check digit does not match. Other codes
// (for example older demo codes) are left for the database to judge.
export function cardCodeLooksValid(code: string): boolean {
  const match = CARD_CODE.exec(code.trim().toUpperCase());
  return !match || luhnCheckDigit(match[1]) === Number(match[2]);
}
